// FUNCTION: BFME2 0x0012D3D0 size=170 name=?Release_Refs@@YAXPAVSortingNodeStruct@@@Z evidence=N:ledger tier=B hypothesis:Z
void Release_Refs(SortingNodeStruct *state)
{
	int i;
	for (i = 0; i < MAX_VERTEX_STREAMS; ++i) {
		if (state->sorting_state.vertex_buffers[i]) {
			state->sorting_state.vertex_buffers[i]->Release_Ref();
			state->sorting_state.vertex_buffers[i] = 0;
		}
	}
	if (state->sorting_state.index_buffer) {
		state->sorting_state.index_buffer->Release_Ref();
		state->sorting_state.index_buffer = 0;
	}
	if (state->sorting_state.material) {
		state->sorting_state.material->Release_Ref();
		state->sorting_state.material = 0;
	}
	for (i = 0; i < DX8Wrapper::Get_Current_Caps()->Get_Max_Textures_Per_Pass(); ++i) {
		state->sorting_state.Textures[i].Clear();
	}
}

// FUNCTION: BFME2 0x0012D480 size=66 name=?Insert_To_Sorting_Pool@SortingRendererClass@@CAXPAVSortingNodeStruct@@@Z evidence=N:ledger tier=B hypothesis:Z
void SortingRendererClass::Insert_To_Sorting_Pool(SortingNodeStruct *state)
{
	if (overlapping_node_count >= MAX_OVERLAPPING_NODES) {
		Release_Refs(state);
		return;
	}

	overlapping_nodes[overlapping_node_count] = state;
	overlapping_vertex_count += state->vertex_count;
	overlapping_polygon_count += state->polygon_count;
	overlapping_node_count++;
}

